Lemma PutL_core : forall d c', PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0) d ->
  pcore_ok c' -> pc_skip c' = pc_skip (ps_c d) ->
  (pc_state c' <= 1 -> pc_state (ps_c d) <= 1) ->
  (pc_state c' = 3 \/ pc_state c' = 4 \/ pc_state c' = 9 -> 1 <= pc_len c') ->
  (pc_state c' < 10 -> pc_hlim c' <= 8192) ->
  PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0)
       (mkPST c' (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) (ps_h d) (ps_u d) (ps_es d) (ps_insz d) (ps_g d) (ps_rdi d) (ps_LBn d) (ps_A d)).
Proof.
  intros d c' L PCOK' SKEQ ST1 LEN' HL'. destruct d as [c S1 L1 ns1 ls1 em1 h u es insz g rdi LBn A].
  destruct L as (PCOK & OWN & MOWN & NEW & NEWB & OFP & OFE & OFW & WINL & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HNEW & HL8 & SK62 & AOWN & LS & ESS & A0).
  cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A] in *.
  unfold PutL. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A].
  repeat (split; [assumption|]). split; [intros K; exact (HST (ST1 K))|]. repeat (split; [assumption|]). split; [rewrite SKEQ; exact SK62|].
  repeat (split; [assumption|]). exact A0.
Qed.

Lemma PutB_core : forall d c' g' q, PutB MX CX MA LB0 p0 R d q -> pc_hlim c' = pc_hlim (ps_c d) ->
  (pc_state c' <= 9 -> pc_state (ps_c d) <= 9) -> (pc_state c' <= 1 -> pc_state (ps_c d) <= 1) ->
  PutB MX CX MA LB0 p0 R (mkPST c' (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) (ps_h d) (ps_u d) (ps_es d) (ps_insz d) g' (ps_rdi d) (ps_LBn d) (ps_A d)) q.
Proof.
  intros d c' g' q (B1 & B2 & B3 & B4) HLEQ S9 S1. unfold PutB in *. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A] in *.
  rewrite HLEQ.
  assert (P9 : (if pc_state c' <=? 9 then 34 else 0) <= (if pc_state (ps_c d) <=? 9 then 34 else 0)).
  { destruct (pc_state c' <=? 9) eqn:K1; [| destruct (pc_state (ps_c d) <=? 9); lia]. apply Z.leb_le in K1.
    replace (pc_state (ps_c d) <=? 9) with true by (symmetry; apply Z.leb_le; exact (S9 K1)). lia. }
  assert (P2 : (if pc_state c' <=? 9 then 2 else 0) <= (if pc_state (ps_c d) <=? 9 then 2 else 0)).
  { destruct (pc_state c' <=? 9) eqn:K1; [| destruct (pc_state (ps_c d) <=? 9); lia]. apply Z.leb_le in K1.
    replace (pc_state (ps_c d) <=? 9) with true by (symmetry; apply Z.leb_le; exact (S9 K1)). lia. }
  assert (P1 : (if pc_state c' <=? 1 then 8 else 0) <= (if pc_state (ps_c d) <=? 1 then 8 else 0)).
  { destruct (pc_state c' <=? 1) eqn:K1; [| destruct (pc_state (ps_c d) <=? 1); lia]. apply Z.leb_le in K1.
    replace (pc_state (ps_c d) <=? 1) with true by (symmetry; apply Z.leb_le; exact (S1 K1)). lia. }
  repeat split; lia.
Qed.
